#!/usr/bin/env python3
"""Generate rule/profile reference files from executable source-of-truth data."""

from __future__ import annotations

import argparse
import json
from pathlib import Path

from ansibleguard.detector_config import DEFAULT_CONFIG
from ansibleguard.profiles import PROFILE_DEFINITIONS
from ansibleguard.report.findings import CONCEPT_IDS, RULE_CATALOG


ROOT = Path(__file__).resolve().parents[1]


def _rule_markdown(payload):
    lines = [
        "# Generated rule reference",
        "",
        "This file is generated by `scripts/generate_docs.py`; do not edit it manually.",
        "",
        "| Rule | Concept | Maturity | Severity | Confidence | Taxonomy | Actionability | Category |",
        "|---|---|---|---|---|---|---|---|",
    ]
    for rule_id, item in payload.items():
        lines.append(
            f"| `{rule_id}` | `{item['concept_id']}` | {item['status']} | "
            f"{item['level']} | {item['confidence']} | {item['taxonomy']} | "
            f"{item['actionability']} | {item['category']} |"
        )
    return "\n".join(lines) + "\n"


def _profile_markdown():
    lines = [
        "# Generated profile reference",
        "",
        "This file is generated by `scripts/generate_docs.py`; do not edit it manually.",
        "",
        "| Profile | Rules | Providers | Manifest required | Research eligible |",
        "|---|---:|---|---|---|",
    ]
    for name, definition in sorted(PROFILE_DEFINITIONS.items()):
        providers = ", ".join(sorted(definition.get("providers", ())))
        lines.append(
            f"| `{name}` | {len(definition.get('rules', ()))} | {providers} | "
            f"{str(bool(definition.get('requires_manifest'))).lower()} | "
            f"{str(bool(definition.get('research_eligible'))).lower()} |"
        )
    lines.extend(
        [
            "",
            "## Default thresholds",
            "",
            "| Setting | Value |",
            "|---|---:|",
            *(
                f"| `{key}` | {value} |"
                for key, value in sorted(DEFAULT_CONFIG["thresholds"].items())
            ),
        ]
    )
    return "\n".join(lines) + "\n"


def generated_files():
    payload = {
        rule_id: {
            **metadata,
            "concept_id": CONCEPT_IDS.get(rule_id, rule_id),
        }
        for rule_id, metadata in sorted(RULE_CATALOG.items())
    }
    return {
        ROOT / "RULE_REFERENCE.generated.md": _rule_markdown(payload),
        ROOT / "PROFILE_REFERENCE.generated.md": _profile_markdown(),
        ROOT / "rule-catalog.json": json.dumps(
            {
                "schema_version": 1,
                "rules": payload,
                "default_config": DEFAULT_CONFIG,
            },
            indent=2,
            sort_keys=True,
        ) + "\n",
    }


def main(argv=None):
    parser = argparse.ArgumentParser()
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args(argv)
    stale = []
    for path, content in generated_files().items():
        if args.check:
            if not path.is_file() or path.read_text(encoding="utf-8") != content:
                stale.append(path.relative_to(ROOT).as_posix())
        else:
            path.write_text(content, encoding="utf-8")
    if stale:
        parser.error("generated documentation is stale: " + ", ".join(stale))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
